
        CREATE TABLE IF NOT EXISTS commerce_ops_suppliers(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,contact TEXT DEFAULT '',note TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
        CREATE TABLE IF NOT EXISTS commerce_ops_customers(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,alias TEXT NOT NULL,note TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
        CREATE TABLE IF NOT EXISTS commerce_ops_purchase_orders(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,supplier_id INTEGER NOT NULL,reference TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',total BIGINT NOT NULL DEFAULT 0 CHECK(total>=0),created_at TIMESTAMPTZ DEFAULT now(),FOREIGN KEY(supplier_id) REFERENCES commerce_ops_suppliers(id));
        CREATE TABLE IF NOT EXISTS commerce_ops_ledger(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>=0),description TEXT NOT NULL,reference TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
        CREATE TABLE IF NOT EXISTS commerce_ops_stock_movements(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,product_id INTEGER NOT NULL,change_qty INTEGER NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
        CREATE TABLE IF NOT EXISTS commerce_ops_inventory_lots(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,product_id INTEGER NOT NULL,lot_code TEXT NOT NULL,expiry_date TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(product_id,lot_code,expiry_date));
        CREATE TABLE IF NOT EXISTS commerce_ops_inventory_disposals(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,lot_id INTEGER NOT NULL,product_id INTEGER NOT NULL,quantity INTEGER NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
        CREATE TABLE IF NOT EXISTS commerce_ops_ops_audit(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,action TEXT NOT NULL,details TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
        